// The generated icon set: PNG for Linux and the window, ICO for Windows, ICNS
// for macOS. Regenerated by `npm run icons` from resources/icons/source.png.
import { readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';

const dir = join(__dirname, '..', '..', 'resources', 'icons');

function pngSize(buf: Buffer): { width: number; height: number; color: number } {
  expect(buf.subarray(0, 8).toString('binary')).toBe('\x89PNG\r\n\x1a\n');
  expect(buf.subarray(12, 16).toString('ascii')).toBe('IHDR');
  return { width: buf.readUInt32BE(16), height: buf.readUInt32BE(20), color: buf[25]! };
}

describe('application icons', () => {
  it('icon.png is a square RGBA image', async () => {
    const png = pngSize(await readFile(join(dir, 'icon.png')));
    expect(png).toMatchObject({ width: 1024, height: 1024, color: 6 });
    const source = pngSize(await readFile(join(dir, 'source.png')));
    expect(source.color).toBe(6);
    expect(source.width).toBeGreaterThanOrEqual(1024);
  });

  it('icon.ico embeds PNGs from 16 to 256', async () => {
    const ico = await readFile(join(dir, 'icon.ico'));
    expect(ico.readUInt16LE(0)).toBe(0);
    expect(ico.readUInt16LE(2)).toBe(1);
    const count = ico.readUInt16LE(4);
    expect(count).toBe(7);
    const sizes: number[] = [];
    for (let i = 0; i < count; i++) {
      const at = 6 + i * 16;
      const w = ico[at] || 256;
      const h = ico[at + 1] || 256;
      expect(w).toBe(h);
      sizes.push(w);
      const bytes = ico.readUInt32LE(at + 8);
      const offset = ico.readUInt32LE(at + 12);
      expect(pngSize(ico.subarray(offset, offset + bytes)).width).toBe(w);
    }
    expect(sizes).toEqual([16, 24, 32, 48, 64, 128, 256]);
  });

  it('icon.icns is a modern PNG icon set including the retina sizes', async () => {
    const icns = await readFile(join(dir, 'icon.icns'));
    expect(icns.subarray(0, 4).toString('ascii')).toBe('icns');
    expect(icns.readUInt32BE(4)).toBe(icns.length);
    const types: string[] = [];
    let at = 8;
    while (at < icns.length) {
      const type = icns.subarray(at, at + 4).toString('ascii');
      const len = icns.readUInt32BE(at + 4);
      const payload = icns.subarray(at + 8, at + len);
      expect(pngSize(payload).width).toBeGreaterThan(0);
      types.push(type);
      at += len;
    }
    expect(types).toEqual([
      'icp4',
      'icp5',
      'ic11',
      'icp6',
      'ic12',
      'ic07',
      'ic13',
      'ic08',
      'ic14',
      'ic09',
      'ic10',
    ]);
  });
});
